            } else {
                $shipper = $sale->shipper;
            }
            $amount = '';
            if ($sale->p_collection_amount != null && $sale->p_collection_amount !=0) {
                $amount = $sale->p_collection_amount;
            } else if ($sale->d_collection_amount != null && $sale->d_collection_amount !=0) {
