                    else
                        return '-';
                })
                ->editColumn('resolved_date', function ($requests) {
                    if ($requests->current_status_id == 3 || $requests->current_status_id == 4) {
                        return $requests->resolved_date;
                    } else {
                        return '-';
                    }
                })
                ->addColumn('responsible_hub', function ($requests) {
                    $responsible_hub = "";
                    $status = $requests->shipment_status_id;
                    $shipment_id = $requests->shipment_id;
                    $origin_hub = $requests->origin_hub;
                    $destination_hub = $requests->hub;
                    $shipment_journey = ShipmentsJourney::whereIn('shipper_status_id', [11, 12, 20, 21, 22])
                        ->where('shipment_id', $shipment_id);
                    if ($shipment_journey->exists()) {
                        $shipment_journey = $shipment_journey->pluck('shipper_status_id')->toArray();
                        if (in_array(11, $shipment_journey) && in_array(12, $shipment_journey)) {
                            $temp = $destination_hub;
                            $destination_hub = $origin_hub;
                            $origin_hub = $temp;
                        }
                    }
                    if ($status == 1 || $status == 2 || $status == 17 || $status == 22) {
                        $responsible_hub = $origin_hub;
                    } elseif ($status == 3 || $status == 21) {
                        $manifest_bag = CargoManifestBagShipments::leftjoin('cargo_manifest_bags as cmb', 'cmb.id', '=', 'cargo_manifest_bag_shipments.cargo_manifest_bag_id')
                            ->leftjoin('cities as c', 'c.id', '=', 'cmb.origin_hub_id')
                            ->leftjoin('cities as cd', 'cd.id', '=', 'cmb.destination_hub_id')
                            ->leftjoin('cities as chi', 'chi.id', '=', 'cmb.current_hub_id')
                            ->where('cargo_manifest_bag_shipments.shipment_id', $shipment_id)
                            ->select(['cargo_manifest_bag_shipments.id', 'cmb.status_id', 'c.name as origin_hub', 'cd.name as destination_hub', 'chi.name as curren_hub_origin'])
                            ->orderby('cargo_manifest_bag_shipments.id', 'desc');
                        if ($manifest_bag->exists()) {
                            $manifest_bag = $manifest_bag->first();
                            if ($manifest_bag->status_id == 0) { //bag created
                                $responsible_hub = $manifest_bag->origin_hub;
                            } elseif ($manifest_bag->status_id == 1) { //bag created
                                $responsible_hub = $manifest_bag->origin_hub;
                            } elseif ($manifest_bag->status_id == 3) { // bag Received at junction
                                $responsible_hub = $manifest_bag->curren_hub_origin;
                            } elseif ($manifest_bag->status_id == 2 || $manifest_bag->status_id == 4 || $manifest_bag->status_id == 5 || $manifest_bag->status_id == 7) {
                                $responsible_hub = $manifest_bag->destination_hub;
                            } elseif ($manifest_bag->status_id == 9) {
                                $responsible_hub = $manifest_bag->curren_hub_origin;
                            }
                        }
                    } elseif ($status == 4 || $status == 12 || $status == 20 || $status == 24 || $status == 11 || $status == 8) {
                        $responsible_hub = $destination_hub;
                    } else {
                        $responsible_hub = "-";
                    }
                    return $responsible_hub;
                })
                ->editColumn('last_status_date', function ($request) {

                    $shipment = Shipment::where('tracking_number', $request->tracking_number)->first();
                    $last_shipment = ShipmentsJourney::where('shipment_id', $shipment->id)->latest()->first();

                    if (!isset($last_shipment)) {
                        return '---';
                    } else {
                        return Carbon::parse($last_shipment->created_at);
                    }
                })
                ->addColumn('responsible_zone', function ($requests) {
                    $responsible_zone = "";
                    $status = $requests->shipment_status_id;
                    $shipment_id = $requests->shipment_id;

                    $origin_zone = $requests->origin_zone;
                    $destination_zone = $requests->zone;
                    $shipment_journey = ShipmentsJourney::whereIn('shipper_status_id', [11, 12, 20, 21, 22])
                        ->where('shipment_id', $shipment_id);
                    if ($shipment_journey->exists()) {
                        $shipment_journey = $shipment_journey->pluck('shipper_status_id')->toArray();
                        if (in_array(11, $shipment_journey) && in_array(12, $shipment_journey)) {
                            $temp = $destination_zone;
                            $destination_zone = $origin_zone;
                            $origin_zone = $temp;
                        }
                    }

                    if ($status == 1 || $status == 2 || $status == 17 || $status == 22) {
                        $responsible_zone = $origin_zone;
                    } elseif ($status == 3 || $status == 21) {
                        $manifest_bag = CargoManifestBagShipments::leftjoin('cargo_manifest_bags as cmb', 'cmb.id', '=', 'cargo_manifest_bag_shipments.cargo_manifest_bag_id')
                            ->leftjoin('cities as c', 'c.id', '=', 'cmb.origin_hub_id')
                            ->leftjoin('zones as cz', 'cz.id', '=', 'c.zone_id')
                            ->leftjoin('cities as cd', 'cd.id', '=', 'cmb.destination_hub_id')
                            ->leftjoin('zones as cdz', 'cdz.id', '=', 'cd.zone_id')
                            ->leftjoin('cities as chi', 'chi.id', '=', 'cmb.current_hub_id')
                            ->leftjoin('zones as chiz', 'chiz.id', '=', 'chi.zone_id')
                            ->where('cargo_manifest_bag_shipments.shipment_id', $shipment_id)
                            ->select(['cargo_manifest_bag_shipments.id', 'cmb.status_id', 'cz.name as origin_zone', 'cdz.name as destination_zone', 'chiz.name as curren_zone_origin'])
                            ->orderby('cargo_manifest_bag_shipments.id', 'desc');
                        if ($manifest_bag->exists()) {
                            $manifest_bag = $manifest_bag->first();
                            if ($manifest_bag->status_id == 0) { //bag created
                                $responsible_zone = $manifest_bag->origin_zone;
                            } elseif ($manifest_bag->status_id == 1) { //bag created
                                $responsible_zone = $manifest_bag->origin_zone;
                            } elseif ($manifest_bag->status_id == 3) { // bag Received at junction
                                $responsible_zone = $manifest_bag->curren_zone_origin;
                            } elseif ($manifest_bag->status_id == 2 || $manifest_bag->status_id == 4 || $manifest_bag->status_id == 5 || $manifest_bag->status_id == 7) {
                                $responsible_zone = $manifest_bag->destination_zone;
                            } elseif ($manifest_bag->status_id == 9) {
                                $responsible_zone = $manifest_bag->curren_zone_origin;
                            }
                        }
                    } elseif ($status == 4 || $status == 12 || $status == 20 || $status == 24 || $status == 11 || $status == 8) {
                        $responsible_zone = $destination_zone;
                    } else {
                        $responsible_zone = '-';
                    }
                    return $responsible_zone;
                })
                ->editColumn('arrival_today', function ($requests)use($current_date) {
                    return ($requests->arrival_date && $current_date) ? with((new Carbon($requests->arrival_date, 'UTC'))->diffInWeekendDays($current_date) - (new Carbon($requests->arrival_date, 'UTC'))->diffInDaysFiltered(function (Carbon $date) {
                            $date->isSunday();
                        }, $current_date)) : '-';
                })
                ->addColumn('shipper_category', function($requests){
                    if($requests->kae != null){
                        return 'Key Account';
                    }else{
                        return 'Non-Key Account';
                    }
                })
                ->addColumn('tagged_manual_auto', function($requests) {
                    $crm_tagging = CrmRequestTagging::where('crm_request_id', $requests->request_number)
                        ->where('crm_request_tagging_type_id', 2)
                        ->first();

                    if($crm_tagging){
                        return (
                            $crm_tagging->tagged_id == '346') ? 'Auto' : 'Manual';
                    }else{
                        return '-';
                    }
                })
               ->addColumn('claim_resolved_invalid_reason', function ($crm_request) {
                    $invalidReasons = CrmInvalidReasonRequest::where('crm_request_id', $crm_request->request_number)
                                        ->with('claimInvalidReason')
                                        ->get();

                    if ($invalidReasons->isNotEmpty()) {
                        $names = $invalidReasons->pluck('claimInvalidReason.reason')->filter()->unique()->toArray();
                        return implode(', ', $names);
                    }

                    $resolvedReasons = CrmRequestResolvedReason::where('crm_request_id', $crm_request->request_number)
                                        ->with('resolvedReason')
                                        ->get();

                    if ($resolvedReasons->isNotEmpty()) {
                        $names = $resolvedReasons->pluck('resolvedReason.name')->filter()->unique()->toArray();
                        return implode(', ', $names);
                    }

                    return '-'; 
                })
                ->addColumn('claim_resolved_sub_reason', function ($crm_request) {
                    $resolvedSubReasons = CrmRequestResolvedReason::where('crm_request_id', $crm_request->request_number)
                        ->with('resolvedSubReason')
                        ->get();

                    if ($resolvedSubReasons->isNotEmpty()) {
                        $names = $resolvedSubReasons->pluck('resolvedSubReason.name')->filter()->unique()->toArray();
                        return implode(', ', $names);
                    }

                    return '-';
                })
                ->orderColumn('launched_by_name', DB::connection('reports')->raw('IF (crm_requests.launched_by = 0, a.name, IF (crm_requests.launched_by = 1, us.name, IF (crm_requests.launched_by = 2, su.name, "")))') . ' $1');



            if ($request->get('excel') && $request->get('excel') == true) {
                $fieldsToRetrieve = $request->input('selectedValue', []);
                $headers = $request->input('selectedTexts',[]);

                $this->fetchCsvCrm($headers,$fieldsToRetrieve,$crm,$select);
                ActivityTrailController::createActivityTrailLog(Auth::id(), 174);
            }else{
                return $datatable
                    ->rawColumns(['tracking_number_link', 'id_padded_link', ''])
                    ->make(true);
            }

        } catch (\Throwable $th) {
            Log::channel('code_test_log')->error(
                "CRM Report Error: " . $th->getMessage(),
                [
                    'trace' => json_encode($th->getTraceAsString()),
                    'line'  => $th->getLine()
                ]
            );
        }
    }

    public function fetchCsvCrm($headers ,$fieldsToRetrieve, $crm,$select)
    {
        try {

            $headers = array_filter($headers, function($value) {
                return $value !== 'Select All';
            });
            $fieldsToRetrieve = array_filter($fieldsToRetrieve, function($value) {
                return $value !== 'selectAll';
            });

            $final_Array = array();
            $specificValues = $crm->select($select)->get()->toarray();


            header('Content-Type: text/csv; charset=utf-8');
            header('Content-Disposition: attachment; filename=data.csv');
            $output = fopen("php://output", "w");
            fputcsv($output, $headers);
            $current_date = Carbon::now();

            foreach ($specificValues as $key => $row) {
                $rowArray = (array) $row;
                // Handle tagging_type conditions
                if (in_array($rowArray['tagging_type'], [2, 4, 5])) {
                    $rowArray['tagged_to'] = Admin::find($rowArray['tagged_id'])->name ?? '-';
                } elseif ($rowArray['tagging_type'] == 1) {
                    $department = AdminDepartment::find($rowArray['tagged_id']);
                    $rowArray['tagged_to'] = $department ? $department->name : '-';
                } else {
                    $rowArray['tagged_to'] = '-';
                }

                // Tracking number link
                $rowArray['tracking_number_link'] =  $rowArray['tracking_number'] ;

                // Valid/Invalid status and date
                if ($rowArray['valid_date'] != null) {
                    $rowArray['valid_invalid_status'] = 'Valid';
                    $rowArray['valid_invalid_date'] = $rowArray['valid_date'];
                } elseif ($rowArray['invalid_date'] != null) {
                    $rowArray['valid_invalid_status'] = 'Invalid';
                    $rowArray['valid_invalid_date'] = $rowArray['invalid_date'];
                } else {
                    $rowArray['valid_invalid_status'] = '-';
                    $rowArray['valid_invalid_date'] = '-';
                }

                // Request number padded
                $rowArray['request_number_padded'] = str_pad($rowArray['request_number'], 6, '0', STR_PAD_LEFT);
                $rowArray['id_padded_link'] = $rowArray['request_number_padded'];

                // Launched by name
                $rowArray['launched_by_name'] = $rowArray['launched_by_type'] == 0 ? $rowArray['name'] : ($rowArray['launched_by_type'] == 1 ? $rowArray['shipper'] : $rowArray['sub_shipper']);

                // Admin department
                $rowArray['admin_department'] = $rowArray['launched_by_type'] == 0 ? $rowArray['admin_department'] : '-';

                // Closed date
                $rowArray['closed_date'] = $rowArray['current_status_id'] == 4 ? $rowArray['closed_date'] : '-';

                // Launched to today
                if ($rowArray['launched_date']) {
                    Carbon::setWeekendDays([Carbon::SUNDAY]);
                    $launched_date = Carbon::parse($rowArray['launched_date']);
                    $days = $launched_date->diffInDays($current_date);
                    $rowArray['launched_to_today'] = $days <= 0 ? '-' : $days;
                } else {
                    $rowArray['launched_to_today'] = '-';
                }

                // Resolved date
                $rowArray['resolved_date'] = in_array($rowArray['current_status_id'], [3, 4]) ? $rowArray['resolved_date'] : '-';

                // Responsible hub
                $status = $rowArray['shipment_status_id'];
                $shipment_id = $rowArray['shipment_id'];
                $origin_hub = $rowArray['origin_hub'];
                $destination_hub = $rowArray['hub'];
                $responsible_hub = "";

                $shipment_journey = ShipmentsJourney::whereIn('shipper_status_id', [11, 12, 20, 21, 22])
                    ->where('shipment_id', $shipment_id);

                if ($shipment_journey->exists()) {
                    $shipment_journey = $shipment_journey->pluck('shipper_status_id')->toArray();
                    if (in_array(11, $shipment_journey) && in_array(12, $shipment_journey)) {
                        $temp = $destination_hub;
                        $destination_hub = $origin_hub;
                        $origin_hub = $temp;
                    }
                }

                if (in_array($status, [1, 2, 17, 22])) {
                    $responsible_hub = $origin_hub;
                } elseif (in_array($status, [3, 21])) {
                    $manifest_bag = CargoManifestBagShipments::leftjoin('cargo_manifest_bags as cmb', 'cmb.id', '=', 'cargo_manifest_bag_shipments.cargo_manifest_bag_id')
                        ->leftjoin('cities as c', 'c.id', '=', 'cmb.origin_hub_id')
                        ->leftjoin('cities as cd', 'cd.id', '=', 'cmb.destination_hub_id')
                        ->leftjoin('cities as chi', 'chi.id', '=', 'cmb.current_hub_id')
                        ->where('cargo_manifest_bag_shipments.shipment_id', $shipment_id)
                        ->select(['cargo_manifest_bag_shipments.id', 'cmb.status_id', 'c.name as origin_hub', 'cd.name as destination_hub', 'chi.name as curren_hub_origin'])
                        ->orderby('cargo_manifest_bag_shipments.id', 'desc');

                    if ($manifest_bag->exists()) {
                        $manifest_bag = $manifest_bag->first();
                        if (in_array($manifest_bag->status_id, [0, 1])) { // Bag created
                            $responsible_hub = $manifest_bag->origin_hub;
                        } elseif ($manifest_bag->status_id == 3) { // Bag received at junction
                            $responsible_hub = $manifest_bag->curren_hub_origin;
                        } elseif (in_array($manifest_bag->status_id, [2, 4, 5, 7])) {
                            $responsible_hub = $manifest_bag->destination_hub;
                        } elseif ($manifest_bag->status_id == 9) {
                            $responsible_hub = $manifest_bag->curren_hub_origin;
                        }
                    }
                } elseif (in_array($status, [4, 12, 20, 24, 11, 8])) {
                    $responsible_hub = $destination_hub;
                } else {
                    $responsible_hub = "-";
                }
                $rowArray['responsible_hub'] = $responsible_hub;

                // Last status date
                $shipment = Shipment::where('tracking_number', $rowArray['tracking_number'])->first();
                $last_shipment = ShipmentsJourney::where('shipment_id', $shipment->id)->latest()->first();
                $rowArray['last_status_date'] = isset($last_shipment) ? Carbon::parse($last_shipment->created_at) : '---';

                // Responsible zone
                $responsible_zone = "";
                $shipment_id = $rowArray['shipment_id'];
                $origin_zone = $rowArray['origin_zone'];
                $destination_zone = $rowArray['zone'];

                $shipment_journey = ShipmentsJourney::whereIn('shipper_status_id', [11, 12, 20, 21, 22])
                    ->where('shipment_id', $shipment_id);

                if ($shipment_journey->exists()) {
                    $shipment_journey = $shipment_journey->pluck('shipper_status_id')->toArray();
                    if (in_array(11, $shipment_journey) && in_array(12, $shipment_journey)) {
                        $temp = $destination_zone;
                        $destination_zone = $origin_zone;
                        $origin_zone = $temp;
                    }
                }

                if (in_array($status, [1, 2, 17, 22])) {
                    $responsible_zone = $origin_zone;
                } elseif (in_array($status, [3, 21])) {
                    $manifest_bag = CargoManifestBagShipments::leftjoin('cargo_manifest_bags as cmb', 'cmb.id', '=', 'cargo_manifest_bag_shipments.cargo_manifest_bag_id')
                        ->leftjoin('cities as c', 'c.id', '=', 'cmb.origin_hub_id')
                        ->leftjoin('zones as cz', 'cz.id', '=', 'c.zone_id')
                        ->leftjoin('cities as cd', 'cd.id', '=', 'cmb.destination_hub_id')
                        ->leftjoin('zones as cdz', 'cdz.id', '=', 'cd.zone_id')
                        ->leftjoin('cities as chi', 'chi.id', '=', 'cmb.current_hub_id')
                        ->leftjoin('zones as chiz', 'chiz.id', '=', 'chi.zone_id')
                        ->where('cargo_manifest_bag_shipments.shipment_id', $shipment_id)
                        ->select(['cargo_manifest_bag_shipments.id', 'cmb.status_id', 'cz.name as origin_zone', 'cdz.name as destination_zone', 'chiz.name as curren_zone_origin'])
                        ->orderby('cargo_manifest_bag_shipments.id', 'desc');

                    if ($manifest_bag->exists()) {
                        $manifest_bag = $manifest_bag->first();
                        if (in_array($manifest_bag->status_id, [0, 1])) { // Bag created
                            $responsible_zone = $manifest_bag->origin_zone;
                        } elseif ($manifest_bag->status_id == 3) { // Bag received at junction
                            $responsible_zone = $manifest_bag->curren_zone_origin;
                        } elseif (in_array($manifest_bag->status_id, [2, 4, 5, 7])) {
                            $responsible_zone = $manifest_bag->destination_zone;
                        } elseif ($manifest_bag->status_id == 9) {
                            $responsible_zone = $manifest_bag->curren_zone_origin;
                        }
                    }
                } elseif (in_array($status, [4, 12, 20, 24, 11, 8])) {
                    $responsible_zone = $destination_zone;
                } else {
                    $responsible_zone = '-';
                }
                $rowArray['responsible_zone'] = $responsible_zone;

                // Arrival today calculation
                if ($rowArray['arrival_date']) {
                    Carbon::setWeekendDays([Carbon::SUNDAY]);
                    $arrival_date = Carbon::parse($rowArray['arrival_date'], 'UTC');

                    $sundays = $arrival_date->diffInDaysFiltered(function (Carbon $date) {
                        return $date->isSunday();
                    }, $current_date);

                    $rowArray['arrival_today'] = ($sundays);
                } else {
                    $rowArray['arrival_today'] = '-';
                }

                // Shipper category
                $rowArray['shipper_category'] = $rowArray['kae'] != null ? 'Key Account' : 'Non-Key Account';

                // Tagged manual/auto
                $crm_tagging = CrmRequestTagging::where('crm_request_id', $rowArray['request_number'])
                    ->where('crm_request_tagging_type_id', 2)
                    ->first();

                if ($crm_tagging) {
                    $rowArray['tagged_manual_auto'] = ($crm_tagging->tagged_id == '346')
                        ? 'Auto'
                        : 'Manual';
                }else {
                    $rowArray['tagged_manual_auto'] = '-';
                }

                switch ($rowArray['launched_by_type']) {
                    case 0:
                        $rowArray['launched_by_type'] = 'Admin';
                        break;
                    case 1:
                        $rowArray['launched_by_type'] = 'Shipper';
                        break;
                    default:
                        $rowArray['launched_by_type'] = 'Shipper Substitute User';
                        break;
                }
                
                
                $invalidReasons = CrmInvalidReasonRequest::where('crm_request_id', $rowArray['request_number'])
                    ->with('claimInvalidReason')
                    ->get();

                if ($invalidReasons->isNotEmpty()) {
                    $names = $invalidReasons->pluck('claimInvalidReason.reason')->filter()->unique()->toArray();
                    $rowArray['claim_resolved_invalid_reason'] = implode(', ', $names);
                } else {
                    $resolvedReasons = CrmRequestResolvedReason::where('crm_request_id', $rowArray['request_number'])
                        ->with('resolvedReason')
                        ->get();

                    if ($resolvedReasons->isNotEmpty()) {
                        $names = $resolvedReasons->pluck('resolvedReason.name')->filter()->unique()->toArray();
                        $rowArray['claim_resolved_invalid_reason'] = implode(', ', $names);
                    } else {
                        $rowArray['claim_resolved_invalid_reason'] = '-';
                    }
                }

                $resolvedSubReasons = CrmRequestResolvedReason::where('crm_request_id', $rowArray['request_number'])
                    ->with('resolvedSubReason')
                    ->get();

                if ($resolvedSubReasons->isNotEmpty()) {
                    $names = $resolvedSubReasons->pluck('resolvedSubReason.name')->filter()->unique()->toArray();
                    $rowArray['claim_resolved_sub_reason'] = implode(', ', $names);
                } else {
                    $rowArray['claim_resolved_sub_reason'] = '-';
                }


                $filteredArray = [];

                // Iterate over $fieldsToRetrieve to maintain sequence
                foreach ($fieldsToRetrieve as $field) {
                    // Check if the field exists in the row array
                    if (array_key_exists($field, $rowArray)) {
                        // Add the field to the filtered array
                        $filteredArray[$field] = $rowArray[$field];
                    }
                }
                $final_Array[] = $rowArray;
                fputcsv($output, $filteredArray);
            }
            fclose($output);
        } catch (\Throwable $th) {
            Log::channel('code_test_log')->error(
                "CRM Report Error: " . $th->getMessage(),
                [
                    'trace' => json_encode($th->getTraceAsString()),
                    'line'  => $th->getLine()
                ]
            );
        }
    }

    public function summary_index(Request $request)
    {
        ActivityTrailController::createActivityTrailLog(Auth::id(), 175);
        $today = Carbon::now()->endOfDay();
        $thirtyDays = Carbon::now()->subDays(30)->startOfDay();
        $shippers = DB::connection('reports')->table('users')->where('status', '=', 3)->where(function($query){
            $idsToExclude = FilterTrait::class::getFilteredIds(auth()->user()->id);
            if (!empty($idsToExclude)) {
                $query->whereNotIn('users.id', $idsToExclude);
            }
        })->get();

        $sales_persons=DB::connection('reports')->table('admins as ad')->join('admin_roles as ar','ad.role_id','=','ar.id')->where('ar.department_id',7)->get(['ad.id','ad.name']);
        $hubs = DB::connection('reports')->table('cities')->select('id', 'name')->get();
        $shipping_modes = DB::connection('reports')->table('shipping_modes')->get(['id', 'mode']);
        $sub_segments = DB::connection('reports')->table('sub_category_segments')->get(['id', 'name']);
        $service_types = DB::connection('reports')->table('booking_types')->get();

        return view('admin.reports.summary')->with(['hubs' => $hubs, 'shippers' => $shippers, 'today' => $today, 'thirtyday' => $thirtyDays, 'shipping_modes' => $shipping_modes, 'sub_segments' => $sub_segments, 'sales_persons' => $sales_persons, 'service_types'=> $service_types ]);
    }

    public function summary_data(Request $request)
    {
        $stats = array();
        $shipper = $request->shipper;
        $from = $request->from_date;
        $to = $request->to_date;
        $origin = $request->origin;
        $destination = $request->destination;
        if ($from == null || $to == null) {
            $toDays = Carbon::now()->endOfDay();
            $fromDays = Carbon::now()->subDays(30)->startOfDay();
        } else {
            $fromDays = $from;
            $toDays = $to;
        }

        $stats['total'] = DB::connection('reports')->table('shipments')->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        $stats['booked'] = DB::connection('reports')->table('shipments')->where('shipper_status_id', 1)->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        $stats['canceled'] = DB::connection('reports')->table('shipments')->where('shipper_status_id', 17)->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        $stats['received'] = DB::connection('reports')->table('shipments')->whereIn('shipper_status_id', [2, 3, 4])->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        $stats['delivered'] = DB::connection('reports')->table('shipments')->whereIn('shipper_status_id', [14, 16, 30, 36, 37, 39, 40, 41, 47])->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        $stats['return'] = DB::connection('reports')->table('shipments')->whereIn('shipper_status_id', [25])->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        $stats['return_intransit'] = DB::connection('reports')->table('shipments')->where('shipper_status_id', 21)->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        $stats['in_process'] = DB::connection('reports')->table('shipments')->whereIn('shipper_status_id', [5, 6, 7, 8, 9, 10, 11, 12, 13, 15, 18, 19, 49, 52])->whereBetween('created_at', [$fromDays, $toDays])->where('user_id', $shipper);
        if ($origin) {
            $stats['total'] = $stats['total']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });
            $stats['booked'] = $stats['booked']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });
            $stats['canceled'] = $stats['canceled']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });
            $stats['received'] = $stats['received']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });
            $stats['delivered'] = $stats['delivered']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });
            $stats['return'] = $stats['return']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });

            $stats['return_intransit'] = $stats['return_intransit']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });


            $stats['in_process'] = $stats['in_process']->whereExists(function ($query) use ($origin) {
                $query->from('user_shipping_infos')
                    ->where('shipments.pickup_address_id', '=', DB::raw('`user_shipping_infos`.`id`'))
                    ->whereExists(function ($sub_query) use ($origin) {
                        $sub_query->from('cities')
                            ->where('user_shipping_infos.city_id', '=', DB::raw('`cities`.`id`'))
                            ->where('cities.id', $origin);
                    });
            });
        }

        if ($destination) {
            $stats['total'] = $stats['total']->where('consignee_city_id', $destination);
            $stats['booked'] = $stats['booked']->where('consignee_city_id', $destination);
            $stats['received'] = $stats['received']->where('consignee_city_id', $destination);
            $stats['canceled'] = $stats['canceled']->where('consignee_city_id', $destination);
            $stats['delivered'] = $stats['delivered']->where('consignee_city_id', $destination);
            $stats['return'] = $stats['return']->where('consignee_city_id', $destination);
            $stats['return_intransit'] = $stats['return_intransit']->where('consignee_city_id', $destination);
            $stats['in_process'] = $stats['in_process']->where('consignee_city_id', $destination);
        }
        $stats['total'] = number_format($stats['total']->count());
        $stats['booked'] = number_format($stats['booked']->count());
        $stats['canceled'] = number_format($stats['canceled']->count());
        $stats['received'] = number_format($stats['received']->count());
        $stats['delivered'] = number_format($stats['delivered']->count());
        $stats['return'] = number_format($stats['return']->count());
        $stats['return_intransit'] = number_format($stats['return_intransit']->count());
        $stats['in_process'] = number_format($stats['in_process']->count());


        return response()->json(['status' => 1, 'stats' => $stats]);
    }

    public function summary_list(Request $request)
    {

        $connection = 'reports';
        if ($request->get('excel') && $request->get('excel') == true) {
            ActivityTrailController::createActivityTrailLog(Auth::id(), 176);
        }
        $from = $request->get('search_date_from');
        $to = $request->get('search_date_to');
        $from_id = null;
        $to_id = null;
        $sj_from_id = 168982787;
        $sj_to_id = 908982787;
        $arrived_sj_to_id = 908982787;

        if ($from != null && $to != null) {

            $from_id = DB::connection($connection)->table('shipments')->select('id')->where('created_at', '>=', $from);
            if ($from_id->exists()) {
                $from_id = $from_id->first()->id;

                $to_id = DB::connection($connection)->table('shipments')->select(DB::raw('MAX(id) as id'))->where('created_at', '>=', $from)->where('created_at', '<=', $to);

                if ($to_id->exists()) {
                    $to_id = $to_id->first()->id;
                }
            }

            $sj_from_id = DB::connection($connection)->table('shipments_journey')->select('id')->where('created_at', '>=', $from);


            if ($sj_from_id->exists()) {
                $sj_from_id = $sj_from_id->first()->id ?? 0;


                $sj_to_id = DB::connection($connection)->table('shipments_journey')->select(DB::raw('MAX(id) as id'))->where('created_at', '>=', $from)->where('created_at', '<=', $to);
                $arrived_sj_to_id = DB::connection($connection)->table('shipments_journey')->select(DB::raw('MAX(id) as id'))->where('created_at', '>=', $from)->where('created_at', '<=', $to)->orWhere('created_at', '>=', $to);

                if ($sj_to_id->exists()) {
                    $sj_to_id = $sj_to_id->first()->id ?? 0;
                    $arrived_sj_to_id = $arrived_sj_to_id->first()->id ?? 0;

                }
            }else{
                $sj_from_id=0;
                $sj_to_id=0;
                $arrived_sj_to_id=0;
            }
        }
        // if(!is_int($sj_from_id)){
        //     dd($sj_from_id);

        //     $shipments = DB::connection($connection)->table('shipments')->whereRaw('false');
        //     return $shipments;
        // }

        $shipments = DB::connection('reports')->table('shipments')->join('users as u', 'u.id', '=', 'shipments.user_id')
            ->join('user_shipping_infos AS usi', 'shipments.pickup_address_id', '=', 'usi.id')
            ->join('cities AS oc', 'usi.city_id', '=', 'oc.id')
            ->join('cities AS dc', 'shipments.consignee_city_id', '=', 'dc.id')
            ->join('cities as h', 'dc.hub_id', '=', 'h.id')
            ->leftJoin('booking_types as bt', 'bt.id', '=', 'shipments.booking_type_id')
            ->join('shipment_status as ss', 'ss.id', '=', 'shipments.shipper_status_id')
            ->join('shipping_modes as sm', 'sm.id', '=', 'shipments.shipping_mode_id')

            ->leftjoin('shipment_payment_status as sps', 'shipments.payment_status_id', '=', 'sps.id')
            ->leftJoin('shipments_journey as sj', function ($join) use ($sj_from_id, $arrived_sj_to_id) {
                $join->on('sj.shipment_id', '=', 'shipments.id')
                    ->where(
                        'sj.id',
                        '=',
                        DB::raw("(select max(id) from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.shipper_status_id = 2 and shipments_journey.id >= $sj_from_id and shipments_journey.id <= $arrived_sj_to_id)"));
            })
            ->leftJoin('shipments_journey as sju', function ($join) use ($sj_from_id, $arrived_sj_to_id) {
                $join->on('sju.shipment_id', '=', 'shipments.id')
                    ->where(
                        'sju.id',
                        '=',
                        DB::raw("(select max(id) from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.id >= $sj_from_id and shipments_journey.id <= $arrived_sj_to_id)"));
            })
            ->leftjoin('shipment_items as si', function ($join) {
                $join->on('si.shipment_id', '=', 'shipments.id')
                    ->where('si.type', '=', 0);
            })
            ->leftJoin('shipments_journey as sjr', function ($join) use ($connection, $sj_from_id, $sj_to_id) {
                $join->on('sjr.shipment_id', '=', 'shipments.id')
                    ->whereIn('shipments.shipper_status_id', [20, 21, 22, 23, 24, 25, 44, 47, 48, 57, 60])
                    ->where(
                        'sjr.id',
                        '=',
                        DB::connection($connection)->raw("(select max(id) from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.shipper_status_id IN (12, 20) and shipments_journey.verification = 1 and shipments_journey.status_reason_id is not null and shipments_journey.id >= $sj_from_id and shipments_journey.id <= $sj_to_id)")
                    );
            })
            ->leftJoin('shipment_status_reason as ssr', 'ssr.id', '=', 'sjr.status_reason_id')
            ->leftJoin('shipments_journey as sjfa', function ($join) use ($connection, $sj_from_id, $sj_to_id) {
                $join->on('sjfa.shipment_id', '=', 'shipments.id')
                    ->where(
                        'sjfa.id',
                        '=',
                        DB::connection($connection)->raw("(select id from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.shipper_status_id  = 5 and shipments_journey.id >= $sj_from_id and shipments_journey.id <= $sj_to_id ORDER BY id ASC 
              LIMIT 1 OFFSET 0)")
                    );
            })
            ->leftJoin('shipments_journey as sjf2', function ($join) use ($connection, $sj_from_id, $sj_to_id) {
                $join->on('sjf2.shipment_id', '=', 'shipments.id')
                    ->where(
                        'sjf2.id',
                        '=',
                        DB::connection($connection)->raw("(select id from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.shipper_status_id  = 5 and shipments_journey.id >= $sj_from_id and shipments_journey.id <= $sj_to_id ORDER BY id ASC 
              LIMIT 1 OFFSET 1)")
                    );
            })
            ->leftJoin('shipments_journey as sjf3', function ($join) use ($connection, $sj_from_id, $sj_to_id) {
                $join->on('sjf3.shipment_id', '=', 'shipments.id')
                    ->where(
                        'sjf3.id',
                        '=',
                        DB::connection($connection)->raw("(select id from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.shipper_status_id  = 5 and shipments_journey.id >= $sj_from_id and shipments_journey.id <= $sj_to_id ORDER BY id ASC 
              LIMIT 1 OFFSET 2)")
                    );
            })
            ->leftJoin('shipments_journey as sjrp', function ($join) use ($connection, $sj_from_id, $sj_to_id) {
                $join->on('sjrp.shipment_id', '=', 'shipments.id')
                    ->where(
                        'sjrp.id',
                        '=',
                        DB::connection($connection)->raw("(select min(id) from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.shipper_status_id  = 53 and shipments_journey.id >= $sj_from_id and shipments_journey.id <= $sj_to_id)")
                    );
            })->leftJoin('sale_person_tags as st', function ($join) {
                $join->on('st.user_id', '=', 'shipments.user_id')->where('st.status', 0);
            })->leftJoin('admins as sd', 'sd.id', '=', 'st.admin_id')
            ->leftjoin('shipment_items as siq', function ($join) {
                $join->on('siq.shipment_id', '=', 'shipments.id')
                    ->where('siq.type', '=', 0);
            })
            ->where(function($query){
                $idsToExclude = FilterTrait::class::getFilteredIds(auth()->user()->id);
                if (!empty($idsToExclude)) {
                    $query->whereNotIn('shipments.user_id', $idsToExclude);
                }
            })
            ->select(['ssr.name as reason', 'sjr.remarks as remark', 'shipments.id as shipment_id', 'shipments.order_id', 'shipments.tracking_number', 'shipments.amount as collection_amount', 'ss.name as current_status', 'sps.name as payment_status', 'bt.booking_type as service_type', 'sj.created_at as arrival_date', 'oc.name as origin', 'dc.name as destination', 'u.name as shipper','u.id as shipper_id', 'shipments.consignee_name', 'shipments.consignee_phone_number_1 as phone1', 'shipments.consignee_phone_number_2 as phone2', 'shipments.consignee_address', 'shipments.created_at as booking_date', 'usi.vendor', DB::raw('(select count(id) from shipments_journey where shipments_journey.shipment_id = shipments.id and shipments_journey.shipper_status_id = 5) as total_attempt'), 'h.name as hub', 'sju.created_at as last_status_date', 'sjfa.created_at as first_attempt_date', 'sjrp.created_at as rider_picked_status_date', 'u.sub_segment_id as sub_segment','shipments.pieces','shipments.actual_weight','sm.mode as shipping_mode','sd.name as sales_person_name','siq.quantity as shipment_quantity', 'sjf2.created_at as second_attempt_date', 'sjf3.created_at as third_attempt_date']);
        /*  if( $request->get('search_shipper')){
              $shipments->where('shipments.user_id', '=',$request->get('search_shipper'));
          }else{
              $shipments->where('shipments.user_id', '=', null);
          }*/


        if ($search_shippers = $request->get('search_shipper')) {
            $shipments = $shipments->whereIn('shipments.user_id', $search_shippers);
        }


        if ($search_sub_segment = $request->get('search_sub_segment')) {
            $shipments = $shipments->where('u.sub_segment_id', $search_sub_segment);
        }


        if ($sales_persons = $request->get('search_sales_person')) {
            // $shippers=SalePersonTag::whereIn('admin_id',$sales_persons)->where('status',1)->pluck('user_id');
            $shipments = $shipments->whereIn('st.admin_id', $sales_persons);
        }



        if ($from != null && $to != null) {
            $shipments = $shipments->whereBetween('shipments.created_at', [$from, $to]);

            if ($from_id != null && $to_id != null) {
                $shipments->where('shipments.id', '>=', $from_id)
                    ->where('shipments.id', '<=', $to_id);
            }
        }

        $datatable = Datatables::of($shipments)
            ->addColumn('tracking_number_link', function ($shipments) {
                $route = route('admin.tracking.index');
                return "<u><a href='{$route}?tracking_number=$shipments->tracking_number' class='tracking' target='_blank'>$shipments->tracking_number</a></u>";
            })
            //            ->editColumn('phone', function ($shipments) {
            //                return $shipments->phone1 . "<br>" . $shipments->phone2;
            //            })
            ->filterColumn('phone', function ($query, $keyword) {
                $keyword = strtolower($keyword);

                $keyword = str_replace('-', '', $keyword);

                if ($keyword != '') {
                    $query->where(function ($sub_query) use ($keyword) {
                        $sub_query->where('shipments.consignee_phone_number_1', 'like', '%' . $keyword . '%')
                            ->orWhere('shipments.consignee_phone_number_2', 'like', '%' . $keyword . '%');
                    });
                } else {
                    $query->whereRaw('false');
                }
            })
            ->orderColumn('phone', 'shipments.consignee_phone_number_1 $1, shipments.consignee_phone_number_2 $1')
            ->editColumn('collection_amount', function ($shipments) {
                return number_format($shipments->collection_amount);
            })
            ->editColumn('sub_segment', function ($shipments) {
                if ($shipments->sub_segment) {
                    $sub_category = SubCategorySegment::where('id', $shipments->sub_segment)->first();
                    return $sub_category['name'];
                } else {
                    return '-';
                }
            });
        //        if($shipper = $request->get('search_shipper')){
        //            $datatable->where('shipments.user_id','=', $shipper);
        //        }
        if ($origin = $request->get('search_origin')) {
            $shipments->where('oc.id', '=', $origin);
        }
        if ($destination = $request->get('search_destination')) {
            $shipments->where('dc.id', '=', $destination);
        }
        if ($mode = $request->get('search_shipping_mode')) {
            $shipments->where('shipments.booking_type_id', '=', $mode);
        }
        if ($card = $request->get('cards_filter')) {
            switch ($card) {
                case 'total':
                    $today = Carbon::now()->endOfDay();
                    $thirtyDays = Carbon::now()->subDays(30)->startOfDay();
                    $shipments->whereBetween('shipments.created_at', [$thirtyDays, $today]);
                    break;
                case 'booked':
                    $shipments->where('shipments.shipper_status_id', 1);
                    break;
                case 'received':
                    $shipments->whereIn('shipments.shipper_status_id', [2, 3, 4]);
                    break;
                case 'delivered':
                    $shipments->whereIn('shipments.shipper_status_id', [14, 16, 30, 36, 37, 39, 40, 41, 47]);
                    break;
                case 'returned':
                    $shipments->whereIn('shipments.shipper_status_id', [25]);
                    break;
                case 'returned_intransit':
                    $shipments->where('shipments.shipper_status_id', 21);
                    break;
                case 'in_process':
                    $shipments->whereIn('shipments.shipper_status_id', [5, 6, 7, 8, 9, 10, 11, 12, 13, 15, 18, 19, 49, 52]);
                    break;
                case 'cancelled':
                    $shipments->where('shipments.shipper_status_id', 17);
                    break;
            }
        }

        if ($service_type_select = $request->get('service_type_select')) {
            $shipments->where('bt.id', '=', $service_type_select);
        }

        return $datatable
        ->rawColumns(['tracking_number_link'])
        ->make(true);
    }

