    public function daily_visit_list(Request $request)
    {
        if ($request->get('excel') && $request->get('excel') == true) {
            ActivityTrailController::createActivityTrailLog(Auth::id(), 194);
        }
        $daily_visit = DB::connection('reports')->table('daily_visits')
            ->join('daily_visit_lead_statuses as dvls', 'dvls.id', '=', 'daily_visits.lead_status_id')
            ->leftjoin('admins as a', 'a.id', '=', 'daily_visits.admin_id')
            ->leftjoin('cities as c', 'c.id', '=', 'a.default_hub_id')
            ->leftjoin('zones as z', 'z.id', '=', 'c.zone_id')
            ->leftjoin('daily_visit_ratings as rate', 'rate.id', 'daily_visits.rating_id')
            ->select(
                'daily_visits.id as id',
                'a.name as admin',
                'daily_visits.admin_id as admin_id',
                'daily_visits.company_name as company_name',
                'daily_visits.customer_name as customer_name',
                'daily_visits.customer_address as customer_address',
                'daily_visits.phone_no as phone_no',
                'daily_visits.email as email',
                'dvls.name as lead_status',
                'daily_visits.feedback as feedback',
                'daily_visits.latitude as latitude',
                'daily_visits.longitude as longitude',
                'daily_visits.created_at as created_at',
                'daily_visits.business_card_image as business_card_image',
                'daily_visits.location_image as location_image',
                'c.name as city',
                'z.name as zone',
                'rate.name as rating_text',
                'daily_visits.comment as rating_comment',
                'rate.code as rating',
                'daily_visits.visit_status as visit_status'
            );

        $multiple_sales_tags = MultipleSaleLead::join('multiple_sale_taggings as mst', 'mst.lead_id', '=', 'multiple_sale_leads.id')
            ->where('multiple_sale_leads.admin_id', Auth::id())
            ->pluck('mst.admin_id')->toArray();

        if (session('role_id') != 1 && (!in_array(session('id'), session('sale_users_bypass')))) {
            if (count($multiple_sales_tags) > 0) {
                array_push($multiple_sales_tags, Auth::id());
                $daily_visit = $daily_visit->whereIn('daily_visits.admin_id', $multiple_sales_tags);
            } else {
                $daily_visit = $daily_visit->where('daily_visits.admin_id', Auth::id());
            }
        }

        $datatables = Datatables::of($daily_visit)
            ->editColumn('b_c_photo', function ($dvr) {
                $image = '';
                if ($dvr->business_card_image != null) {
                    $image .= '<div class="text-center"><button type="button" class="btn btn-primary btn-sm"><a class="white" href=' . route('admin.daily_visit.business_card', [$dvr->business_card_image]) . ' target="_blank">View</a></button></div>';
                    return $image;
                } else {
                    return '-';
                }
            })
            ->editColumn('l_photo', function ($dvr) {
                $image = '';
                if ($dvr->location_image != null) {
                    $image .= '<div class="text-center"><button type="button" class="btn btn-primary btn-sm"><a class="white" href=' . route('admin.daily_visit.location_photo', [$dvr->location_image]) . ' target="_blank">View</a></button></div>';
                    return $image;
                } else {
                    return '-';
                }
            })
            ->editColumn('location', function ($dvr) {
                $location = '<div class="text-center">';
                if ($dvr->latitude != null && $dvr->longitude != null) {
                    $location .= '<button type="button" class="btn btn-primary btn-sm"><a class="white" href="http://www.google.com/maps/place/' . $dvr->latitude . ',' . $dvr->longitude . '" target="_blank"><i class="la la-map-marker align-middle"></i></a></button>';
                    return $location;
                } else {
                    return '-';
                }
            })

            ->editColumn('visit_status', function ($dvr) {
                $visit_status = '';
                if ($dvr->visit_status == 1) {
                    $visit_status .= 'Valid';
                    return $visit_status;
                } else if ($dvr->visit_status == 2) {
                    $visit_status .= 'Invalid';
                    return $visit_status;
                } else {
                    $visit_status .= '-';
                    return $visit_status;
                }
            })


            ->addColumn('action', function ($daily_visit) {
                if (session('role_id') == 1 && (!in_array(session('id'), session('sale_users_bypass')))) {

                    $valid_visit = '<button type="button" class="dropdown-item enable" data-visit-status="1"><div class="row no-gutters align-items-center"><div class="col-2"><i class="ft-check-circle"></i></div><div class="col-9 offset-1">Valid Visit</div></button>';
                    $invalid_visit = '<button type="button" class="dropdown-item disable" data-visit-status="2"><div class="row no-gutters align-items-center"><div class="col-2"><i class="ft-x-circle"></i></div><div class="col-9 offset-1">Invalid Visit</div></button>';

                    $dropdown = '
                    <div class="btn-group">
                        <button type="button" class="btn btn-sm btn-success dropdown-toggle" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">Actions</button>
                        <div class="dropdown-menu dropdown-menu-sm">
                ';

                    if ($daily_visit->visit_status == 2) {
                        $dropdown .= $valid_visit;
                    } elseif ($daily_visit->visit_status == 1) {
                        $dropdown .= $invalid_visit;
                    } else {
                        $dropdown .= $valid_visit . $invalid_visit;
                    }

                    $dropdown .= '
                        </div>
                    </div>
                ';

                    return $dropdown;
                }
            });


        //AdminUser Filter
        if ($team_member = $request->get('team_member')) {
            $daily_visit->where('a.id', $team_member);
        }

        if ($rating = $request->get('rating')) {
            $daily_visit->where('daily_visits.rating_id', $rating);
        }
        //VisitDate filter
        if ($request->get('search_date_from') && $request->get('search_date_to')) {
            $from = $request->get('search_date_from');
            $to = $request->get('search_date_to');
            $daily_visit->whereBetween('daily_visits.created_at', [$from, $to]);
        }

        return $datatables
        ->rawColumns(['b_c_photo', 'l_photo', 'location', 'action'])
        ->make(true);
    }


    public function set_visit_status(Request $request)
    {
        $set_status = DailyVisit::find($request->daily_visit_id);
        if ($set_status) {
            $set_status->visit_status = $request->visit_status;
            $set_status->save();
            return array('status' => 'success', 'message' => 'Visit Status Updated Successfully');
        } else {
            return array('status' => 'error', 'message' => 'Visit Status Updated Failed');
        }
    }

