    public function route_distribution_list(Request $request)
    {

        if ($request->get('excel') && $request->get('excel') == true) {
            ActivityTrailController::createActivityTrailLog(Auth::id(), 198);
        }

        $count = DB::connection('reports')->table('delivery_notes')
            ->join('riders as r', 'r.id', '=', 'delivery_notes.rider_id')
            ->leftjoin('cities as c', 'c.id', '=', 'delivery_notes.hub_id');

        if ($rider = $request->get('search_rider')) {
            $count = $count->where('r.id', '=', $rider);
        }
        if ($hub = $request->get('search_hub')) {
            $count = $count->where('c.hub_id', '=', $hub);
        }
        if ($zone = $request->get('search_zone')) {
            $count = $count->where('c.zone_id', '=', $zone);
        }
        if ($destination = $request->get('search_destination')) {
            $count = $count->where('c.id', '=', $destination);
        }
        if ($search_rider_cat = $request->get('search_rider_cat')) {
            $count = $count->where('r.operation_rider_id', $search_rider_cat);
        }

        $from = $request->get('search_from');
        $to = $request->get('search_to');
        if ($from == null || $to == null) {
            $from = Carbon::now()->endOfDay();
            $to = Carbon::now()->subDays(30)->startOfDay();
        }
        $count = $count->whereBetween('delivery_notes.created_at', [$from, $to])->groupBy('r.id')->count();

        $route_distribution_summary = DB::connection('reports')->table('delivery_notes')
            ->leftjoin('riders as r', 'r.id', '=', 'delivery_notes.rider_id')
            ->leftjoin('rider_types as rt', 'r.rider_type_id', '=', 'rt.id')
            ->leftjoin('operation_riders_categories as rd', 'r.operation_rider_id', '=', 'rd.id')
            ->leftjoin('cities as c', 'c.id', '=', 'delivery_notes.hub_id')
            ->leftjoin('delivery_note_shipments as dns', 'dns.delivery_note_id', '=', 'delivery_notes.id')
            ->leftJoin('shipments as s', 's.id', '=', 'dns.shipment_id')
            ->leftJoin('shipments_journey as ds', function ($join) {
                $join->on('ds.shipment_id', '=', 's.id')
                    ->where(
                        'ds.id',
                        '=',
                        DB::connection('reports')->raw('(select max(id) from shipments_journey where shipments_journey.shipment_id = s.id and shipments_journey.reference_1_id = delivery_notes.id and shipments_journey.shipper_status_id in (14, 30, 36, 37) and verification = 1)')
                    );
            })
            ->leftJoin('shipments_journey as cps', function ($join) {
                $join->on('cps.shipment_id', '=', 's.id')
                    ->where(
                        'cps.id',
                        '=',
                        DB::connection('reports')->raw('(select max(id) from shipments_journey where shipments_journey.shipment_id = s.id and shipments_journey.reference_1_id = delivery_notes.id and shipments_journey.shipper_status_id = 12 and verification = 1)')
                    );
            })
            ->leftJoin('shipments_journey as us', function ($join) {
                $join->on('us.shipment_id', '=', 's.id')
                    ->where(
                        'us.id',
                        '=',
                        DB::connection('reports')->raw('(select max(id) from shipments_journey where shipments_journey.shipment_id = s.id and shipments_journey.reference_1_id = delivery_notes.id and shipments_journey.shipper_status_id in (7,8,9,15,18,56) and verification = 1)')
                    );
            })
            ->select(
                'r.name as courier_name',
                DB::raw('count(s.id) as shipments_count'),
                DB::raw('count(ds.id) as delivered_shipments'),
                DB::raw('count(cps.id) as confirmation_pending_shipments'),
                DB::raw('count(us.id) as undelivered_shipments'),
                'c.name as hub',
                DB::raw('count(DISTINCT delivery_notes.id) as dn_no_count'),
                DB::raw('GROUP_CONCAT(DISTINCT delivery_notes.id) as dn_ids'),
                'rt.name as rider_type',
                'delivery_notes.id as delivery_note',
                'r.trax_id as rider_trax_id',
                'r.id as rider_id'
            )
            ->groupBy('r.id');



        $datatables = Datatables::of($route_distribution_summary)
            ->setTotalRecords($count)
            ->addColumn('dn_no', function ($entry) {
                $function = "dn_no_pop('" . $entry->dn_ids . "')";
                if ($entry->dn_no_count > 0) {
                    return '<button class="btn btn-sm btn-outline-info align-middle" onclick="' . $function . '" >' . $entry->dn_no_count . '</button>';
                } else {
                    return 0;
                }
            })
            ->addColumn('dncc_amount', function ($entry) {
                $dn_ids = explode(',', $entry->dn_ids);
                return DB::connection('reports')->table('delivery_notes')->whereIn('id', $dn_ids)->sum('received_cod_amount');
            })
            ->addColumn('hbl_konnect_amount', function ($entry) {
                $dn_ids = explode(',', $entry->dn_ids);
                return DB::connection('reports')->table('hbl_konnect_transaction_delivery_notes')->whereIn('delivery_note_id', $dn_ids)->sum('transactions_amount');
            })
            ->editColumn('hbl_konnect_amount_percent', function ($entry) {
                $dn_ids = explode(',', $entry->dn_ids);
                $dncc_amount = DB::connection('reports')->table('delivery_notes')->whereIn('id', $dn_ids)->sum('received_cod_amount');

                $hbl_konnect_amount = DB::connection('reports')->table('hbl_konnect_transaction_delivery_notes')->whereIn('delivery_note_id', $dn_ids)->sum('transactions_amount');

                if ($hbl_konnect_amount > 0 && $dncc_amount > 0) {
                    return round(($hbl_konnect_amount / $dncc_amount) * 100, 2);
                } else {
                    return '-';
                }
            })
            ->editColumn('fintech_shipments_charges', function ($entry) {
                $delivery_note_shipment = DeliveryNoteShipment::where('delivery_note_id', $entry->delivery_note)->pluck('shipment_id')->toArray();
                $amount = TraxPayTransaction::join('fintech_payment_details as fpd', 'fpd.trax_pay_id', '=', 'trax_pay_transactions.id')->whereIn('trax_pay_transactions.shipment_id', $delivery_note_shipment)->sum('fpd.cod_amount');
                if ($amount > 0) {
                    return $amount;
                } else {
                    return 0;
                }
            })
            ->editColumn('fintech_amount_percent', function ($entry) {

                $dn_ids = explode(',', $entry->dn_ids);
                $dncc_amount = DB::connection('reports')->table('delivery_notes')->whereIn('id', $dn_ids)->sum('received_cod_amount');
                $delivery_note_shipment = DeliveryNoteShipment::where('delivery_note_id', $entry->delivery_note)->pluck('shipment_id')->toArray();
                $fintech_amount = TraxPayTransaction::join('fintech_payment_details as fpd', 'fpd.trax_pay_id', '=', 'trax_pay_transactions.id')->whereIn('trax_pay_transactions.shipment_id', $delivery_note_shipment)->sum('fpd.cod_amount');
                if ($fintech_amount > 0 && $dncc_amount > 0) {
                    return round(($fintech_amount / $dncc_amount) * 100, 2);
                } else {
                    return 0;
                }
            })
            ->addColumn('delivered_shipments_per', function ($entry) {
                if ($entry->shipments_count) {
                    return round(($entry->delivered_shipments / $entry->shipments_count) * 100, 2);
                } else {
                    return '';
                }
            })
            ->addColumn('undelivered_shipments_per', function ($entry) {
                if ($entry->shipments_count) {
                    return round(($entry->undelivered_shipments / $entry->shipments_count) * 100, 2);
                } else {
                    return '';
                }
            })
            ->addColumn('confirmation_pending_shipments_per', function ($entry) {
                if ($entry->shipments_count) {
                    return round(($entry->confirmation_pending_shipments / $entry->shipments_count) * 100, 2);
                } else {
                    return '';
                }
            })
            ->addColumn('pending_shipments', function ($entry) {
                if ($entry->shipments_count) {
                    return ($entry->shipments_count - ($entry->undelivered_shipments + $entry->delivered_shipments + $entry->confirmation_pending_shipments));
                } else {
                    return '';
                }
            })
            ->addColumn('pending_shipments_per', function ($entry) {
                if ($entry->shipments_count) {
                    return round((($entry->shipments_count - ($entry->undelivered_shipments + $entry->delivered_shipments + $entry->confirmation_pending_shipments)) / $entry->shipments_count) * 100, 2);
                } else {
                    return '';
                }
            })
            ->addColumn('rider_city_area', function ($entry) {
                if ($entry->rider_id) {
                    $rider = Rider::find($entry->rider_id);
                    if(isset($rider->area)){
                        return $rider->area->name;
                    }else{
                        return '-';
                    }
                }
            })
            ->addColumn('excel_ecom_cod', function($result){
                $count = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $count = DeliveryController::get_segment_type('delivery_note_shipments', $dn_ids, 2, 5, null,'delivery_note_id');
                return $count > 0 ? $count : '-';
            })
            ->addColumn('excel_general_retail', function($result){
                $count = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $count = DeliveryController::get_segment_type('delivery_note_shipments', $dn_ids, 1, 12, null, 'delivery_note_id');
                return $count > 0 ? $count : '-';
            })
            ->addColumn('excel_general_ecom_express', function($result){
                $count_general = 0;
                $count_ecomm = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $count_general = DeliveryController::get_segment_type('delivery_note_shipments', $dn_ids, 1, 2, null,'delivery_note_id');
                $count_ecomm = DeliveryController::get_segment_type('delivery_note_shipments', $dn_ids, 2, 7, null,'delivery_note_id');
                $total_count = $count_general + $count_ecomm;
                return $total_count > 0 ? $total_count : '-';
            })
            ->addColumn('excel_others', function($result){
                $count = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $count = DeliveryController::get_segment_type('delivery_note_shipments', $dn_ids, [1,2], [1,3,4,6,8,9,10,11], null, 'delivery_note_id');
                return $count > 0 ? $count : '-';
            })
            ->addColumn('delivered_excel_ecom_cod', function($result){
                $count = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $delivered_shipments = DeliveryController::get_delivered_shipments($dn_ids);
                if (!empty($delivered_shipments)) {
                    $count = DeliveryController::get_segment_type('delivery_note_shipments', $delivered_shipments, 2, 5, 'delivered', 'delivery_note_id');
                }

                return $count > 0 ? $count : '-';
            })
            ->addColumn('delivered_excel_general_retail', function($result){
                $count = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $delivered_shipments = DeliveryController::get_delivered_shipments($dn_ids);
                if (!empty($delivered_shipments)) {
                    $count = DeliveryController::get_segment_type('delivery_note_shipments', $delivered_shipments, 1, 12, 'delivered', 'delivery_note_id');
                }

                return $count > 0 ? $count : '-';
            })
            ->addColumn('delivered_excel_general_ecom_express', function($result){
                $count_general = 0;
                $count_ecomm = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $delivered_shipments = DeliveryController::get_delivered_shipments($dn_ids);
                if (!empty($delivered_shipments)) {
                    $count_general = DeliveryController::get_segment_type('delivery_note_shipments', $delivered_shipments, 1, 2, 'delivered', 'delivery_note_id');
                    $count_ecomm = DeliveryController::get_segment_type('delivery_note_shipments', $delivered_shipments, 2, 7, 'delivered', 'delivery_note_id');
                }
                $total_count = $count_general + $count_ecomm;
                return $total_count > 0 ? $total_count : '-';
            })
            ->addColumn('delivered_excel_others', function($result){
                $count = 0;
                $dn_ids = explode(',' , $result->dn_ids);
                $delivered_shipments = DeliveryController::get_delivered_shipments($dn_ids);
                if (!empty($delivered_shipments)) {
                    $count = DeliveryController::get_segment_type('delivery_note_shipments', $delivered_shipments, [1,2], [1,3,4,6,8,9,10,11], 'delivered', 'delivery_note_id');
                }

                return $count > 0 ? $count : '-';
            });

        if ($rider = $request->get('search_rider')) {
            $route_distribution_summary = $route_distribution_summary->where('r.id', '=', $rider);
        }
        if ($hub = $request->get('search_hub')) {
