                $rowArray['total_attempt'] = $delivery_notes_count;
            } else {
                $rowArray['total_attempt'] = '-';
            }

            //format tracking_number
            if (isset($rowArray['tracking_number']) && $rowArray['tracking_number']) {
                $rowArray['tracking_number'] = '="' . $rowArray['tracking_number'] .'"' ;
